{"packet_id":"D033-02","doc_id":"D033","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken hardship rental increase requires Board approval","requirement":"A landlord may not impose any rent increase under Article II without Board approval. For a hardship increase, the landlord must serve each tenant notice of the appeal at least 20 days before the hearing and show it is not earning a fair return.","key_value":null,"coverage_conditions":"Rent increases imposed on any tenant under Article II of the Hoboken rent leveling and stabilization chapter; newly constructed dwellings and buildings vacant since January 1, 1984 may be exempt.","applicability":{"conditions":[{"type":"other","text":"newly constructed dwellings eligible for exemption"},{"type":"other","text":"buildings completely vacant since January 1, 1984 eligible for exemption"}],"per_tenancy":null,"coverage_quotes":["The Regulation Officer shall make all determinations regarding the eligibility of a newly constructed dwelling for an exemption as defined above.","The Rent Regulation Officer shall make all determinations regarding the eligibility of a building completely vacant since January 1, 1984, for an exemption as defined above."]},"exemptions":"Newly constructed dwellings and buildings completely vacant since January 1, 1984, whose eligibility for exemption is determined by the Regulation Officer and the Rent Regulation Officer (§ 155-16).","penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken, N.J., Code § 155-14","quoted_span":"No landlord shall impose upon any tenant an increase in rent under this Article without first obtaining approval with the Board.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D033-02","doc_id":"D033","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken capital improvement surcharge tenant notice","requirement":"After the Board approves a capital improvement surcharge application, the landlord must personally serve tenants a standardized notice explaining the surcharge, base rent, apportioned surcharge, effective date and termination, and total rent, and file it with the Board and the Officer.","key_value":null,"coverage_conditions":"Landlords granted a capital improvement surcharge by the Board for dwellings under Article II of the Hoboken rent leveling chapter; newly constructed dwellings and buildings vacant since January 1, 1984 may be exempt.","applicability":{"conditions":[{"type":"other","text":"newly constructed dwellings eligible for exemption"},{"type":"other","text":"buildings completely vacant since January 1, 1984 eligible for exemption"}],"per_tenancy":null,"coverage_quotes":["The Regulation Officer shall make all determinations regarding the eligibility of a newly constructed dwelling for an exemption as defined above.","The Rent Regulation Officer shall make all determinations regarding the eligibility of a building completely vacant since January 1, 1984, for an exemption as defined above."]},"exemptions":"Newly constructed dwellings and buildings completely vacant since January 1, 1984, whose eligibility for exemption is determined by the Regulation Officer and the Rent Regulation Officer (§ 155-16).","penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken, N.J., Code § 155-13","quoted_span":"The landlord shall, upon approval by the Board of its capital improvement surcharge application, notify its tenants by personal service, on a standardized form, setting forth:","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
